fun twoSum(numbers: IntArray, target: Int): IntArray {
    val seen = mutableMapOf<Int, Int>()
    for (i in numbers.indices) {
        val wanted = target - numbers[i]
        for (j in i + 1 until numbers.size) {
            if (numbers[j] == wanted) return intArrayOf(i, j)
        }
        seen[numbers[i]] = i
    }
    return intArrayOf()

